1	// GPU access for named agents in one workspace Box.
2	//
3	// Agents get the GPU through their manifest (`containerSecurity.gpu: true`,
4	// D14) or through `ploinky gpu grant --agent REPO/AGENT`; `ploinky gpu revoke`
5	// denies agents or turns manifest defaults off. The operator's decision lives
6	// in the host-only `~/.ploinky-box/gpu-grants/<instance>.json`, never in the
7	// workspace, because agents can write the workspace bind. Host discovery then
8	// derives the exact wiring for the outer Box: explicit `--device` nodes, one
9	// read-only bind per driver library (under its soname in
10	// `/usr/local/nvidia/lib64`), a read-only `nvidia-smi`, a hookless CDI spec at
11	// `/etc/cdi/ploinky-gpu.json` for the nested Podman, and a read-only grant
12	// marker that in-Box admission checks. The wiring is content addressed: its
13	// fingerprint names the generation directory holding the spec and marker, and
14	// it is recorded on the Box as a label. A changed fingerprint (a new grant or
15	// a driver update) is a Box replacement reason. When discovery fails the Box is
16	// wired only with a marker that says the grant is stale, so the rest of the
17	// workspace keeps running and only GPU-requesting agents fail admission.
18	
19	import { spawnSync } from 'node:child_process';
20	import crypto from 'node:crypto';
21	import fs from 'node:fs';
22	import os from 'node:os';
23	import path from 'node:path';
24	
25	import {
26	    BOX_GPU_BIN_DIRECTORY,
27	    BOX_GPU_CDI_DEVICE,
28	    BOX_GPU_CDI_KIND,
29	    BOX_GPU_CDI_SPEC_PATH,
30	    BOX_GPU_LIBRARY_DIRECTORY,
31	    BOX_GPU_MARKER_PATH,
32	    BOX_LABELS,
33	    GPU_GRANT_STATE_DIRECTORY,
34	} from './constants.mjs';
35	import { PloinkyBoxError } from './errors.mjs';
36	import { assertRouterBindingStateConfined } from './routerBinding.mjs';
37	import {
38	    GPU_GRANT_MARKER_KIND,
39	    GPU_GRANT_MARKER_VERSION,
40	    normalizeGpuAgentSelector,
41	} from './lib/gpuGrantMarker.mjs';
42	
43	export { GPU_GRANT_STATE_DIRECTORY };
44	export const GPU_GRANT_STATE_VERSION = 1;
45	export const GPU_GRANT_STATE_MAX_BYTES = 16 * 1024;
46	export const GPU_GRANT_VENDORS = Object.freeze(['nvidia']);
47	
48	const BOX_BASE_DEVICES = Object.freeze(['/dev/fuse', '/dev/net/tun']);
49	const NVIDIA_DEVICE_NODES = Object.freeze(['/dev/nvidia0', '/dev/nvidiactl', '/dev/nvidia-uvm']);
50	// Measured on CUDA workloads: the driver API library, the PTX JIT that some
51	// runtimes load, and NVML for nvidia-smi are required. NVVM and gpucomp are
52	// bound when present.
53	const NVIDIA_REQUIRED_LIBRARIES = Object.freeze([
54	    'libcuda.so.1',
55	    'libnvidia-ptxjitcompiler.so.1',
56	    'libnvidia-ml.so.1',
57	]);
58	const NVIDIA_OPTIONAL_LIBRARIES = Object.freeze(['libnvidia-nvvm.so.4']);
59	const NVIDIA_SMI_CANDIDATES = Object.freeze([
60	    '/usr/bin/nvidia-smi',
61	    '/usr/local/bin/nvidia-smi',
62	    '/bin/nvidia-smi',
63	    '/usr/sbin/nvidia-smi',
64	]);
65	const LDCONFIG_CANDIDATES = Object.freeze(['/usr/sbin/ldconfig', '/sbin/ldconfig']);
66	const SONAME_RE = /^lib[A-Za-z0-9._+-]+\.so(?:\.[0-9]+)+$/;
67	const FINGERPRINT_RE = /^[a-f0-9]{64}$/;
68	const RECORD_KEYS = Object.freeze([
69	    'admitted',
70	    'agents',
71	    'instance',
72	    'pathHash',
73	    'vendor',
74	    'version',
75	    'workspaceRoot',
76	]);
77	// Written only when set, so a record without denies stays byte-identical.
78	const OPTIONAL_RECORD_KEYS = Object.freeze(['denied', 'workspaceDenied']);
79	// A workspace declares at most this many GPU agents through manifests.
80	const MAX_DECLARED_GPU_AGENTS = 64;
81	
82	function grantError(message, code = 'PLOINKY_BOX_GPU_GRANT_INVALID', cause) {
83	    return new PloinkyBoxError(message, { code, cause });
84	}
85	
86	function discoveryError(message, cause) {
87	    return new PloinkyBoxError(message, { code: 'PLOINKY_BOX_GPU_DISCOVERY_FAILED', cause });
88	}
89	
90	function stateError(message, cause) {
91	    return new PloinkyBoxError(message, { code: 'PLOINKY_BOX_GPU_GRANT_STATE_INVALID', cause });
92	}
93	
94	function currentUid() {
95	    return typeof process.getuid === 'function' ? process.getuid() : null;
96	}
97	
98	function canonicalJson(value) {
99	    if (Array.isArray(value)) return `[${value.map(canonicalJson).join(',')}]`;
100	    if (value && typeof value === 'object') {
101	        return `{${Object.keys(value).sort()
102	            .map((key) => `${JSON.stringify(key)}:${canonicalJson(value[key])}`).join(',')}}`;
103	    }
104	    return JSON.stringify(value);
105	}
106	
107	function sha256(text) {
108	    return crypto.createHash('sha256').update(text).digest('hex');
109	}
110	
111	function exactIdentity(identity) {
112	    const instance = String(identity?.instance || '');
113	    if (!/^ploinky-box-[a-z0-9-]+-[a-f0-9]{12}$/.test(instance)
114	        || !/^[a-f0-9]{12}$/.test(String(identity?.pathHash || ''))
115	        || !path.isAbsolute(String(identity?.workspaceRoot || ''))) {
116	        throw stateError('GPU grant state requires the exact workspace identity');
117	    }
118	    return identity;
119	}
120	
121	/** The vendor a grant uses when --vendor is omitted: the only supported one. */
122	export function defaultGpuVendor(vendors = GPU_GRANT_VENDORS) {
123	    if (vendors.length === 1) return vendors[0];
124	    throw grantError(`Several GPU vendors are supported; choose one with --vendor; supported: ${vendors.join(', ')}`);
125	}
126	
127	export function normalizeGpuVendor(value) {
128	    const vendor = String(value || '').trim().toLowerCase();
129	    if (!GPU_GRANT_VENDORS.includes(vendor)) {
130	        throw grantError(
131	            `Unsupported GPU vendor ${JSON.stringify(String(value || ''))}; supported: ${GPU_GRANT_VENDORS.join(', ')}`,
132	        );
133	    }
134	    return vendor;
135	}
136	
137	export function normalizeGpuAgentSelectors(values) {
138	    if (!Array.isArray(values)) throw grantError('GPU grant agents must be a list of REPO/AGENT selectors');
139	    const normalized = [...new Set(values.map((value) => {
140	        try {
141	            return normalizeGpuAgentSelector(value);
142	        } catch (error) {
143	            throw grantError(error.message, 'PLOINKY_BOX_GPU_GRANT_INVALID', error);
144	        }
145	    }))].sort();
146	    if (normalized.length > 64) throw grantError('A GPU grant names at most 64 agents');
147	    return Object.freeze(normalized);
148	}
149	
150	/** Operator decision: a vendor and the agents that may request the GPU. */
151	export function normalizeGpuGrant(grant) {
152	    if (!grant) return null;
153	    const agents = normalizeGpuAgentSelectors(grant.agents);
154	    if (agents.length === 0) throw grantError('A GPU grant names at least one agent (--agent REPO/AGENT)');
155	    return Object.freeze({ vendor: normalizeGpuVendor(grant.vendor), agents });
156	}
157	
158	/**
159	 * The operator's whole GPU decision for a workspace (D14): agents it granted,
160	 * agents it denied (overriding their manifests), and a workspace-wide deny of
161	 * manifest defaults. Null when it records nothing.
162	 */
163	export function normalizeGpuDecision(decision) {
164	    if (!decision) return null;
165	    const agents = normalizeGpuAgentSelectors(decision.agents ?? []);
166	    const denied = normalizeGpuAgentSelectors(decision.denied ?? []);
167	    if (agents.some((agent) => denied.includes(agent))) {
168	        throw grantError('A GPU decision cannot both grant and deny the same agent');
169	    }
170	    if (decision.workspaceDenied !== undefined && typeof decision.workspaceDenied !== 'boolean') {
171	        throw grantError('A GPU decision workspace deny must be boolean');
172	    }
173	    const workspaceDenied = decision.workspaceDenied === true;
174	    if (!agents.length && !denied.length && !workspaceDenied) return null;
175	    return Object.freeze({
176	        vendor: normalizeGpuVendor(decision.vendor ?? defaultGpuVendor()),
177	        agents,
178	        denied,
179	        workspaceDenied,
180	    });
181	}
182	
183	/**
184	 * The agents a Box's GPU wiring names (D14): the operator's grants plus the
185	 * manifest-declared agents, minus the operator's denies; a workspace deny
186	 * hides every manifest default. `denied` and `workspaceDenied` are reported
187	 * only when they hide a declared agent, so an ineffective deny never changes
188	 * the wiring.
189	 */
190	export function effectiveGpuAccess(decision, declared = []) {
191	    const normalized = normalizeGpuDecision(decision);
192	    const declaredAgents = [...new Set(declared)].sort();
193	    const operator = normalized?.agents ?? [];
194	    const deniedAll = normalized?.denied ?? [];
195	    const workspaceDenied = normalized?.workspaceDenied === true;
196	    const fromManifest = workspaceDenied ? [] : declaredAgents.filter((agent) => !deniedAll.includes(agent));
197	    const agents = [...new Set([...operator, ...fromManifest])].sort();
198	    return Object.freeze({
199	        vendor: normalized?.vendor ?? defaultGpuVendor(),
200	        agents: Object.freeze(agents),
201	        sources: Object.freeze(agents.map((agent) => Object.freeze({
202	            agent,
203	            sources: Object.freeze([
204	                ...(fromManifest.includes(agent) ? ['manifest'] : []),
205	                ...(operator.includes(agent) ? ['operator'] : []),
206	            ]),
207	        }))),
208	        declared: Object.freeze(declaredAgents),
209	        operatorAgents: operator,
210	        denied: Object.freeze(deniedAll.filter((agent) => declaredAgents.includes(agent) && !agents.includes(agent))),
211	        workspaceDenied: workspaceDenied && declaredAgents.some((agent) => !agents.includes(agent)),
212	        decision: normalized,
213	    });
214	}
215	
216	// ---------------------------------------------------------------------------
217	// Host discovery
218	// ---------------------------------------------------------------------------
219	
220	function defaultReadLdconfig() {
221	    for (const candidate of LDCONFIG_CANDIDATES) {
222	        const result = spawnSync(candidate, ['-p'], { encoding: 'utf8', timeout: 10_000 });
223	        if (result.error?.code === 'ENOENT') continue;
224	        if (result.status !== 0) {
225	            throw discoveryError(`${candidate} -p failed with status ${result.status}`);
226	        }
227	        return String(result.stdout || '');
228	    }
229	    throw discoveryError('ldconfig was not found, so the NVIDIA driver libraries cannot be located');
230	}
231	
232	/** Map each x86-64 soname to its first (highest-priority) ldconfig entry. */
233	export function parseLdconfigCache(output) {
234	    const entries = new Map();
235	    for (const line of String(output || '').split('\n')) {
236	        const match = /^\s*(\S+)\s+\(([^)]*)\)\s+=>\s+(\S+)\s*$/.exec(line);
237	        if (!match) continue;
238	        const [, soname, flags, target] = match;
239	        if (!flags.split(',').includes('x86-64') || !path.isAbsolute(target)) continue;
240	        if (!entries.has(soname)) entries.set(soname, target);
241	    }
242	    return entries;
243	}
244	
245	export function parseNvidiaDriverVersion(text) {
246	    const match = /Kernel Module(?:\s+for\s+\S+)?\s+([0-9]+(?:\.[0-9]+)+)/.exec(String(text || ''));
247	    return match ? match[1] : null;
248	}
249	
250	function deviceNumbers(rdev) {
251	    const value = BigInt(rdev);
252	    const major = Number(((value >> 8n) & 0xfffn) | ((value >> 32n) & ~0xfffn));
253	    const minor = Number((value & 0xffn) | ((value >> 12n) & ~0xffn));
254	    return { major, minor };
255	}
256	
257	function describeFile(fsApi, source, label) {
258	    let real;
259	    try {
260	        real = fsApi.realpathSync(source);
261	    } catch (error) {
262	        throw discoveryError(`${label} ${source} cannot be resolved: ${error.code || error.message}`, error);
263	    }
264	    let stat;
265	    try {
266	        stat = fsApi.statSync(real);
267	        fsApi.accessSync(real, fs.constants.R_OK);
268	    } catch (error) {
269	        throw discoveryError(`${label} ${real} is not readable: ${error.code || error.message}`, error);
270	    }
271	    if (!stat.isFile()) throw discoveryError(`${label} ${real} is not a regular file`);
272	    return { source: real, size: stat.size, mtimeMs: Math.trunc(stat.mtimeMs) };
273	}
274	
275	/**
276	 * Discover the NVIDIA device nodes, driver libraries and nvidia-smi on this
277	 * host. Refuses, naming the item, when anything is missing, inaccessible to
278	 * this rootless user, or when the loaded kernel module and the userspace
279	 * libraries disagree (a driver updated but not yet rebooted).
280	 */
281	export function discoverNvidiaGpu({
282	    fsApi = fs,
283	    procVersionPath = '/proc/driver/nvidia/version',
284	    readLdconfig = defaultReadLdconfig,
285	    smiCandidates = NVIDIA_SMI_CANDIDATES,
286	} = {}) {
287	    let versionText;
288	    try {
289	        versionText = fsApi.readFileSync(procVersionPath, 'utf8');
290	    } catch (error) {
291	        throw discoveryError(
292	            `The NVIDIA kernel module is not loaded (${procVersionPath}: ${error.code || error.message})`,
293	            error,
294	        );
295	    }
296	    const driverVersion = parseNvidiaDriverVersion(versionText);
297	    if (!driverVersion) throw discoveryError(`Unable to read the NVIDIA kernel module version from ${procVersionPath}`);
298	
299	    const devices = NVIDIA_DEVICE_NODES.map((devicePath) => {
300	        let stat;
301	        try {
302	            stat = fsApi.statSync(devicePath);
303	        } catch (error) {
304	            throw discoveryError(
305	                `NVIDIA device node ${devicePath} is missing (${error.code || error.message}); `
306	                + 'rootless Ploinky cannot create device nodes',
307	                error,
308	            );
309	        }
310	        if (!stat.isCharacterDevice()) throw discoveryError(`${devicePath} is not a character device`);
311	        try {
312	            fsApi.accessSync(devicePath, fs.constants.R_OK | fs.constants.W_OK);
313	        } catch (error) {
314	            throw discoveryError(
315	                `NVIDIA device node ${devicePath} is not readable and writable by this user (${error.code || error.message})`,
316	                error,
317	            );
318	        }
319	        return { path: devicePath, ...deviceNumbers(stat.rdev) };
320	    });
321	
322	    const cache = parseLdconfigCache(readLdconfig());
323	    const versionedName = (source) => path.basename(source).endsWith(`.so.${driverVersion}`);
324	    const libraries = [];
325	    for (const soname of NVIDIA_REQUIRED_LIBRARIES) {
326	        const target = cache.get(soname);
327	        if (!target) throw discoveryError(`NVIDIA driver library ${soname} is not in the ldconfig cache`);
328	        const file = describeFile(fsApi, target, `NVIDIA driver library ${soname}`);
329	        if (!versionedName(file.source)) {
330	            throw discoveryError(
331	                `NVIDIA driver version mismatch: the kernel module is ${driverVersion} but ${soname} is `
332	                + `${path.basename(file.source)}; reboot after a driver update`,
333	            );
334	        }
335	        libraries.push({ soname, ...file });
336	    }
337	    for (const soname of [...NVIDIA_OPTIONAL_LIBRARIES, `libnvidia-gpucomp.so.${driverVersion}`]) {
338	        const target = cache.get(soname);
339	        if (!target) continue;
340	        const file = describeFile(fsApi, target, `NVIDIA driver library ${soname}`);
341	        if (!versionedName(file.source)) {
342	            throw discoveryError(
343	                `NVIDIA driver version mismatch: the kernel module is ${driverVersion} but ${soname} is `
344	                + `${path.basename(file.source)}; reboot after a driver update`,
345	            );
346	        }
347	        libraries.push({ soname, ...file });
348	    }
349	
350	    const smi = smiCandidates.find((candidate) => {
351	        try {
352	            return fsApi.statSync(candidate).isFile();
353	        } catch {
354	            return false;
355	        }
356	    });
357	    if (!smi) throw discoveryError(`nvidia-smi was not found (checked ${smiCandidates.join(', ')})`);
358	    const tool = describeFile(fsApi, smi, 'nvidia-smi');
359	
360	    return Object.freeze({
361	        vendor: 'nvidia',
362	        driverVersion,
363	        devices: Object.freeze(devices.map((entry) => Object.freeze(entry))),
364	        libraries: Object.freeze(libraries.map((entry) => Object.freeze(entry))),
365	        tools: Object.freeze([Object.freeze({ name: 'nvidia-smi', ...tool })]),
366	    });
367	}
368	
369	export function discoverGpu(vendor, options = {}) {
370	    if (normalizeGpuVendor(vendor) === 'nvidia') return discoverNvidiaGpu(options);
371	    throw grantError(`Unsupported GPU vendor ${vendor}`);
372	}
373	
374	// ---------------------------------------------------------------------------
375	// Wiring
376	// ---------------------------------------------------------------------------
377	
378	function stateRootFor(homeDirectory) {
379	    return path.join(path.resolve(homeDirectory), '.ploinky-box');
380	}
381	
382	export function gpuGrantDirectory(homeDirectory = os.homedir()) {
383	    return path.join(stateRootFor(homeDirectory), GPU_GRANT_STATE_DIRECTORY);
384	}
385	
386	export function gpuGenerationDirectory(identity, fingerprint, homeDirectory = os.homedir()) {
387	    exactIdentity(identity);
388	    if (!FINGERPRINT_RE.test(String(fingerprint))) throw stateError('GPU wiring fingerprint is invalid');
389	    return path.join(gpuGrantDirectory(homeDirectory), identity.instance, fingerprint);
390	}
391	
392	function singleLine(text, limit = 300) {
393	    const flat = String(text || '').replace(/\s+/g, ' ').trim();
394	    return flat.length > limit ? `${flat.slice(0, limit)}…` : flat;
395	}
396	
397	export function renderBoxCdiSpec(discovery) {
398	    return `${JSON.stringify({
399	        cdiVersion: '0.6.0',
400	        kind: BOX_GPU_CDI_KIND,
401	        devices: [{
402	            name: BOX_GPU_CDI_DEVICE.split('=')[1],
403	            containerEdits: {
404	                deviceNodes: discovery.devices.map((device) => ({ path: device.path })),
405	            },
406	        }],
407	        containerEdits: {
408	            mounts: [
409	                ...discovery.libraries.map((library) => path.posix.join(BOX_GPU_LIBRARY_DIRECTORY, library.soname)),
410	                ...discovery.tools.map((tool) => path.posix.join(BOX_GPU_BIN_DIRECTORY, tool.name)),
411	            ].map((inBoxPath) => ({
412	                hostPath: inBoxPath,
413	                containerPath: inBoxPath,
414	                options: ['ro', 'nosuid', 'nodev', 'bind'],
415	            })),
416	        },
417	    }, null, 2)}\n`;
418	}
419	
420	/**
421	 * Desired Box GPU wiring for one workspace, derived from the operator grant
422	 * and either a successful host discovery (active) or its failure (stale).
423	 * Returns null when there is no grant.
424	 */
425	export function buildGpuWiring({
426	    identity,
427	    grant,
428	    discovery = null,
429	    failure = null,
430	    revoked = false,
431	    denied = [],
432	    workspaceDenied = false,
433	    homeDirectory = os.homedir(),
434	}) {
435	    exactIdentity(identity);
436	    let normalizedGrant;
437	    if (revoked) {
438	        // Marker-only: the effective set is empty because the operator denied
439	        // declared agents, and admission must be able to say so.
440	        if (discovery || failure) throw grantError('A revoked GPU wiring carries no discovery');
441	        normalizedGrant = Object.freeze({
442	            vendor: normalizeGpuVendor(grant?.vendor ?? defaultGpuVendor()),
443	            agents: Object.freeze([]),
444	        });
445	    } else {
446	        normalizedGrant = normalizeGpuGrant(grant);
447	        if (!normalizedGrant) return null;
448	        if (!discovery && !failure) throw grantError('GPU wiring requires a discovery result or its failure');
449	    }
450	    const deniedAgents = normalizeGpuAgentSelectors(denied);
451	    if (revoked && !deniedAgents.length && !workspaceDenied) {
452	        throw grantError('A revoked GPU wiring names the denied agents or the workspace deny');
453	    }
454	    // Present only when set, so wirings without denies keep their fingerprint
455	    // and marker bytes.
456	    const denials = {
457	        ...(deniedAgents.length ? { denied: deniedAgents } : {}),
458	        ...(workspaceDenied ? { workspaceDenied: true } : {}),
459	    };
460	    const state = revoked ? 'revoked' : discovery ? 'active' : 'stale';
461	    const reason = discovery || revoked ? null : singleLine(failure?.message || failure);
462	    // The fingerprint binds the exact workspace, the operator decision and the
463	    // discovered driver files, so it names one generation of one workspace.
464	    const fingerprint = sha256(canonicalJson({
465	        ...denials,
466	        version: 1,
467	        instance: identity.instance,
468	        pathHash: identity.pathHash,
469	        workspaceRoot: identity.workspaceRoot,
470	        vendor: normalizedGrant.vendor,
471	        agents: normalizedGrant.agents,
472	        state,
473	        reason,
474	        driverVersion: discovery?.driverVersion ?? null,
475	        devices: discovery?.devices ?? [],
476	        libraries: discovery?.libraries ?? [],
477	        tools: discovery?.tools ?? [],
478	    }));
479	    const generation = gpuGenerationDirectory(identity, fingerprint, homeDirectory);
480	    const specText = discovery ? renderBoxCdiSpec(discovery) : null;
481	    const markerText = `${JSON.stringify({
482	        version: GPU_GRANT_MARKER_VERSION,
483	        kind: GPU_GRANT_MARKER_KIND,
484	        instance: identity.instance,
485	        pathHash: identity.pathHash,
486	        workspaceRoot: identity.workspaceRoot,
487	        vendor: normalizedGrant.vendor,
488	        agents: normalizedGrant.agents,
489	        state,
490	        reason,
491	        fingerprint,
492	        cdiDevice: discovery ? BOX_GPU_CDI_DEVICE : null,
493	        specSha256: specText ? sha256(specText) : null,
494	        ...denials,
495	    }, null, 2)}\n`;
496	    const specPath = path.join(generation, 'box.json');
497	    const markerPath = path.join(generation, 'marker.json');
498	    const mounts = [
499	        ...(discovery ? [
500	            ...discovery.libraries.map((library) => ({
501	                source: library.source,
502	                destination: path.posix.join(BOX_GPU_LIBRARY_DIRECTORY, library.soname),
503	            })),
504	            ...discovery.tools.map((tool) => ({
505	                source: tool.source,
506	                destination: path.posix.join(BOX_GPU_BIN_DIRECTORY, tool.name),
507	            })),
508	            { source: specPath, destination: BOX_GPU_CDI_SPEC_PATH },
509	        ] : []),
510	        { source: markerPath, destination: BOX_GPU_MARKER_PATH },
511	    ].sort((left, right) => left.destination.localeCompare(right.destination));
512	    return Object.freeze({
513	        fingerprint,
514	        state,
515	        reason,
516	        vendor: normalizedGrant.vendor,
517	        agents: normalizedGrant.agents,
518	        denied: deniedAgents,
519	        workspaceDenied: workspaceDenied === true,
520	        driverVersion: discovery?.driverVersion ?? null,
521	        devices: Object.freeze((discovery?.devices ?? []).map((device) => device.path)),
522	        mounts: Object.freeze(mounts.map((mount) => Object.freeze(mount))),
523	        files: Object.freeze([
524	            ...(specText ? [Object.freeze({ path: specPath, content: specText })] : []),
525	            Object.freeze({ path: markerPath, content: markerText }),
526	        ]),
527	    });
528	}
529	
530	/** The operator grant plus a fresh discovery; discovery failure means stale. */
531	export function resolveGpuWiring(identity, grant, {
532	    discover = discoverGpu,
533	    homeDirectory = os.homedir(),
534	} = {}) {
535	    const normalizedGrant = normalizeGpuGrant(grant);
536	    if (!normalizedGrant) return null;
537	    try {
538	        return buildGpuWiring({
539	            identity,
540	            grant: normalizedGrant,
541	            discovery: discover(normalizedGrant.vendor),
542	            homeDirectory,
543	        });
544	    } catch (error) {
545	        if (error?.code !== 'PLOINKY_BOX_GPU_DISCOVERY_FAILED') throw error;
