const MARKER_MAX_BYTES = 16 * 1024;
const SPEC_MAX_BYTES = 256 * 1024;
const MARKER_KEYS = Object.freeze([
    'agents',
    'cdiDevice',
    'fingerprint',
    'instance',
    'kind',
    'pathHash',
    'reason',
    'specSha256',
    'state',
    'vendor',
    'version',
    'workspaceRoot',
]);
// Present only when the operator's denies hide a manifest-declared agent (D14).
const OPTIONAL_MARKER_KEYS = Object.freeze(['denied', 'workspaceDenied']);
