        present: true,
        valid: true,
        digest,
        vendor: String(marker.vendor),
        agents: Object.freeze(agents),
        denied: Object.freeze(denied),
        workspaceDenied,
        state: marker.state,
        reason: marker.reason === null ? null : String(marker.reason),
        fingerprint: marker.fingerprint,
        cdiDevice: marker.cdiDevice,
    });
}
